package com.gathin.tvhome;

/** Embedded single-page Web UI for Wi-Fi Wallpaper & Settings Backup Sync (no internet needed). */
final class WebUi {
    private WebUi() {}

    static final String HTML = "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"utf-8\">"
            + "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
            + "<title>CleanYourTV Wi-Fi Sync</title><style>"
            + ":root{--bg:#111318;--card:#1a1c22;--border:#2d313c;--accent:#a8c7fa;--text:#e3e2e6;--muted:#9aa0a6;--danger:#f28b82;--ok:#81c995;}"
            + "*{box-sizing:border-box;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;}"
            + "body{margin:0;padding:20px 16px 40px;background:var(--bg);color:var(--text);display:flex;justify-content:center;}"
            + ".wrap{width:100%;max-width:480px;}h1{margin:0 0 6px;font-size:23px;font-weight:700;}"
            + ".sub{margin:0 0 18px;color:var(--muted);font-size:14px;}"
            + ".card{background:var(--card);border:1px solid var(--border);border-radius:16px;padding:18px;margin-bottom:14px;}"
            + "label{display:block;font-size:12px;color:var(--accent);margin-bottom:8px;font-weight:600;letter-spacing:.06em;}"
            + "input[type=tel]{width:100%;padding:12px;border-radius:10px;border:1px solid var(--border);background:#0c0e13;color:var(--text);font-size:18px;letter-spacing:6px;text-align:center;}"
            + ".drop{border:2px dashed var(--border);border-radius:14px;padding:18px;text-align:center;cursor:pointer;}"
            + ".drop input{display:none;}.preview{width:100%;max-height:200px;object-fit:cover;border-radius:10px;margin-top:10px;display:none;}"
            + ".row{display:flex;gap:10px;margin-top:12px;flex-wrap:wrap;}"
            + "button{flex:1;min-width:120px;padding:11px 14px;border:0;border-radius:10px;font-size:14px;font-weight:600;cursor:pointer;color:#062e6f;background:var(--accent);}"
            + "button.sec{background:#252832;color:var(--text);}button.dan{background:#3a2026;color:var(--danger);}button:disabled{opacity:.45;cursor:not-allowed;}"
            + ".st{font-size:13px;color:var(--muted);display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #252832;}"
            + ".st:last-child{border-bottom:0;}.b{font-weight:600;color:var(--text);}"
            + ".msg{margin-top:12px;padding:10px 12px;border-radius:10px;font-size:13px;display:none;}"
            + ".msg.ok{display:block;background:#163329;color:var(--ok);}.msg.err{display:block;background:#3b1c22;color:var(--danger);}"
            + "</style></head><body><div class=\"wrap\">"
            + "<h1>CleanYourTV Wi-Fi Sync</h1><p class=\"sub\">Push wallpapers or back up launcher settings over local Wi-Fi.</p>"
            + "<div class=\"card\"><label for=\"pin\">PAIRING PIN (SHOWN ON TV)</label>"
            + "<input id=\"pin\" type=\"tel\" maxlength=\"4\" placeholder=\"0000\" autocomplete=\"off\"></div>"
            + "<div class=\"card\"><label>WALLPAPER (JPG, PNG, WEBP)</label>"
            + "<label class=\"drop\" for=\"file\"><span id=\"fn\">Tap to pick an image</span>"
            + "<input id=\"file\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\">"
            + "<img id=\"prev\" class=\"preview\" alt=\"Preview\"></label>"
            + "<div class=\"row\"><button id=\"bH\" disabled onclick=\"up('home')\">Set Home</button>"
            + "<button id=\"bS\" disabled onclick=\"up('screensaver')\">Set Screensaver</button></div>"
            + "<div class=\"row\"><button id=\"bB\" class=\"sec\" disabled onclick=\"up('both')\">Set Both</button></div>"
            + "<div id=\"msg\" class=\"msg\"></div></div>"
            + "<div class=\"card\"><label>TV STATUS</label>"
            + "<div class=\"st\"><span>Home wallpaper</span><span id=\"stH\" class=\"b\">...</span></div>"
            + "<div class=\"st\"><span>Screensaver wallpaper</span><span id=\"stS\" class=\"b\">...</span></div>"
            + "<div class=\"row\"><button class=\"dan\" onclick=\"clr('home')\">Reset Home</button>"
            + "<button class=\"dan\" onclick=\"clr('screensaver')\">Reset Screensaver</button></div></div>"
            + "<div class=\"card\"><label>LAYOUT &amp; SETTINGS BACKUP (JSON)</label>"
            + "<div class=\"row\"><button class=\"sec\" onclick=\"dlBak()\">Download Backup</button>"
            + "<button class=\"sec\" onclick=\"document.getElementById('bakFile').click()\">Restore Backup</button></div>"
            + "<input id=\"bakFile\" type=\"file\" accept=\"application/json,.json\" style=\"display:none\" onchange=\"upBak(this.files[0])\">"
            + "<div id=\"bmsg\" class=\"msg\"></div></div></div><script>"
            + "const pin=document.getElementById('pin'),file=document.getElementById('file'),prev=document.getElementById('prev'),msg=document.getElementById('msg'),bmsg=document.getElementById('bmsg');"
            + "pin.value=localStorage.getItem('tv_wp_pin')||'';pin.addEventListener('input',()=>localStorage.setItem('tv_wp_pin',pin.value.trim()));"
            + "let sf=null;file.addEventListener('change',()=>{const f=file.files[0];if(!f)return;sf=f;document.getElementById('fn').textContent=f.name;prev.src=URL.createObjectURL(f);prev.style.display='block';setB(false);});"
            + "function setB(d){['bH','bS','bB'].forEach(i=>document.getElementById(i).disabled=d||!sf);}"
            + "function sm(el,t,ok){el.textContent=t;el.className='msg '+(ok?'ok':'err');}"
            + "async function ref(){try{const r=await fetch('/api/status');const j=await r.json();document.getElementById('stH').textContent=j.homeSet?'Custom':'Theme default';document.getElementById('stS').textContent=j.screensaverSet?'Custom':'Follows Home';}catch(e){}}"
            + "async function prep(f){if(f.size<=10*1024*1024)return f;const im=await createImageBitmap(f),sc=Math.min(1,3840/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*sc);c.height=Math.round(im.height*sc);c.getContext('2d').drawImage(im,0,0,c.width,c.height);return new Promise(r=>c.toBlob(r,'image/jpeg',0.9));}"
            + "async function up(t){if(!sf)return;setB(true);sm(msg,'Uploading...',true);try{const b=await prep(sf),r=await fetch('/api/wallpaper?target='+t,{method:'POST',headers:{'X-Pin':pin.value.trim()},body:b}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Failed');sm(msg,'Applied to TV!',true);ref();}catch(e){sm(msg,e.message||'Failed',false);}setB(false);}"
            + "async function clr(t){try{const r=await fetch('/api/clear?target='+t,{method:'POST',headers:{'X-Pin':pin.value.trim()}}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Failed');sm(msg,'Reset '+t+'.',true);ref();}catch(e){sm(msg,e.message||'Failed',false);}}"
            + "async function dlBak(){try{const r=await fetch('/api/backup',{headers:{'X-Pin':pin.value.trim()}});if(!r.ok){const j=await r.json();throw new Error(j.error||'Failed');}const txt=await r.text();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'application/json'}));a.download='cleanyourtv-backup.json';a.click();sm(bmsg,'Backup downloaded!',true);}catch(e){sm(bmsg,e.message||'Failed',false);}}"
            + "async function upBak(f){if(!f)return;try{const txt=await f.text();const r=await fetch('/api/backup',{method:'POST',headers:{'X-Pin':pin.value.trim(),'Content-Type':'application/json'},body:txt}),j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Failed');sm(bmsg,'Backup restored on TV!',true);}catch(e){sm(bmsg,e.message||'Restore failed',false);}}"
            + "ref();</script></body></html>";

    static final byte[] HTML_BYTES = HTML.getBytes(java.nio.charset.StandardCharsets.UTF_8);
}
